bool EmailTemplates::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("template_key"))
    {
        if(!validJsonOfField(1, "template_key", pJson["template_key"], err, true))
            return false;
    }
    else
    {
        err="The template_key column cannot be null";
        return false;
    }
    if(pJson.isMember("locale"))
    {
        if(!validJsonOfField(2, "locale", pJson["locale"], err, true))
            return false;
    }
    if(pJson.isMember("subject"))
    {
        if(!validJsonOfField(3, "subject", pJson["subject"], err, true))
            return false;
    }
    else
    {
        err="The subject column cannot be null";
        return false;
    }
    if(pJson.isMember("body_html"))
    {
        if(!validJsonOfField(4, "body_html", pJson["body_html"], err, true))
            return false;
    }
    else
    {
        err="The body_html column cannot be null";
        return false;
    }
    if(pJson.isMember("body_text"))
    {
        if(!validJsonOfField(5, "body_text", pJson["body_text"], err, true))
            return false;
    }
    if(pJson.isMember("updated_at"))
    {
        if(!validJsonOfField(6, "updated_at", pJson["updated_at"], err, true))
            return false;
    }
    return true;
}
